const float BOX_COLLISION_OFFSET = 0.00001f;
const float BOX_WIDTH = 10.f;

for (size_t i = start; i < end; ++i) {
    Particle& p = particles[i];

    // Calculate acceleration: (force / density) + gravity
    glm::vec3 acceleration = (p.force / p.density) + glm::vec3(0.0f, g, 0.0f);

    // Update velocity: v = v + a * dt
    p.velocity += acceleration * deltaTime;

    // Update position: x = x + v * dt
    p.position += p.velocity * deltaTime;

    // Handle collisions with box boundaries
    // Assuming box is centered at origin with boundaries [-boxWidth, boxWidth] for each axis
    // The particle radius is considered to be 'h/2', so we adjust boundaries accordingly.
    const float minBound = -boxWidth + h;
    const float maxBound = boxWidth - h;

    // Y-axis collisions (bottom and top)
    if (p.position.y < minBound) {
        p.position.y = -p.position.y + 2.0f * minBound + BOX_COLLISION_OFFSET;
        p.velocity.y = -p.velocity.y * elasticity;
    }

    if (p.position.y > maxBound) {
        p.position.y = -p.position.y + 2.0f * maxBound - BOX_COLLISION_OFFSET;
        p.velocity.y = -p.velocity.y * elasticity;
    }

    // X-axis collisions (left and right)
    if (p.position.x < minBound) {
        p.position.x = -p.position.x + 2.0f * minBound + BOX_COLLISION_OFFSET;
        p.velocity.x = -p.velocity.x * elasticity;
    }

    if (p.position.x > maxBound) {
        p.position.x = -p.position.x + 2.0f * maxBound - BOX_COLLISION_OFFSET;
        p.velocity.x = -p.velocity.x * elasticity;
    }

    // Z-axis collisions (front and back)
    if (p.position.z < minBound) {
        p.position.z = -p.position.z + 2.0f * minBound + BOX_COLLISION_OFFSET;
        p.velocity.z = -p.velocity.z * elasticity;
    }

    if (p.position.z > maxBound) {
        p.position.z = -p.position.z + 2.0f * maxBound - BOX_COLLISION_OFFSET;
        p.velocity.z = -p.velocity.z * elasticity;
    }

    // Update the transformation matrix for rendering
    if (particleTransforms != nullptr) {
        particleTransforms[i] = glm::translate(p.position) * glm::scale(glm::vec3(h / 2.0f));
    }
}

